function mountWeightImport(host){
  const section=document.createElement('details');section.className='shift-progress-chart';section.innerHTML='<summary>Bring your weight history (optional)</summary><button type="button" data-weight-export>Download recorded weights (CSV)</button><p>Export uses the recorded weights available in this Progress view; it excludes projections. Your account export holds the wider saved history.</p><p>Preview a CSV with the exact headings <code>date,weight_kg</code>. Up to 365 readings. Dates use YYYY-MM-DD; weights must be kilograms. No automatic medicine-history import.</p><form><label>Choose CSV<input type="file" accept=".csv,text/csv" required></label><button>Preview readings</button></form><p data-import-status role="status"></p><div data-import-preview></div>';host.append(section);const status=section.querySelector('[data-import-status]'),preview=section.querySelector('[data-import-preview]');let rows=null,version=0;
  section.querySelector('[data-weight-export]').onclick=()=>{const byDay=new Map();for(const r of chartData?.metrics?.find(m=>m.key==='weight')?.series||[])if(/^\d{4}-\d{2}-\d{2}$/.test(r.on)&&typeof r.value==='number'&&Number.isFinite(r.value))byDay.set(r.on,r.value);if(!byDay.size){status.textContent='No recorded weights are available to export yet.';return;}const text='date,weight_kg\n'+[...byDay].sort((a,b)=>a[0].localeCompare(b[0])).map(([on,value])=>on+','+value).join('\n'),url=URL.createObjectURL(new Blob([text],{type:'text/csv'})),link=document.createElement('a');link.href=url;link.download='my-timber-recorded-weights.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Recorded weights downloaded to this device. Nothing has been shared.';};
  section.querySelector('input').onchange=()=>{++version;rows=null;preview.replaceChildren();};section.querySelector('form').onsubmit=async e=>{e.preventDefault();const v=++version;rows=null;preview.replaceChildren();const file=section.querySelector('input').files[0];if(!file||file.size>32000){status.textContent='Choose a CSV smaller than 32 KB.';return;}try{const lines=(await file.text()).replace(/^\uFEFF/,'').trim().split(/\r?\n/);if(v!==version||document.hidden||!section.isConnected)return;if(lines.shift()!=='date,weight_kg')throw Error('Use exactly date,weight_kg as the first row.');const seen=new Set(),today=new Date().toISOString().slice(0,10);rows=lines.map(line=>{const a=line.split(','),on=a[0],weightKg=Number(a[1]);if(a.length!==2||!/^\d{4}-\d{2}-\d{2}$/.test(on)||!Number.isFinite(Date.parse(on))||new Date(on).toISOString().slice(0,10)!==on||on>today||!a[1].trim()||!Number.isFinite(weightKg)||weightKg<20||weightKg>400||seen.has(on))throw Error('Check the dates and kilogram weights. Use one reading per date.');seen.add(on);return{on,weightKg};});if(!rows.length||rows.length>365)throw Error('Use 1–365 readings.');status.textContent=rows.length+' readings ready to review. Nothing has been saved.';preview.innerHTML='<details open><summary>Readings to import</summary><table><thead><tr><th>Date</th><th>Weight (kg)</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.on)+'</td><td>'+esc(r.weightKg)+'</td></tr>').join('')+'</tbody></table></details><p>Existing weight records for the same dates are kept. Import saves the remaining readings privately as member-reported history.</p><button data-import-confirm>Confirm import</button>';preview.querySelector('button').onclick=async()=>{const button=preview.querySelector('button');button.disabled=true;try{const response=await fetch((window.SST_API_BASE||'https://api.shiftsometimber.co.uk').replace(/\/$/,'')+'/v1/progress/import',{method:'POST',credentials:'include',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({rows})}),b=await response.json();if(v!==version||document.hidden||!section.isConnected)return;if(!response.ok){if(response.status===401||response.status===409){clearPrivatePhotos();chartData=null;host.replaceChildren();host.textContent=response.status===401?'Please sign in again.':'Review optional health tracking before importing.';return;}throw Error(b.message||'Import could not be confirmed. Preview again before retrying.');}rows=null;preview.replaceChildren();status.textContent=b.imported+' readings imported; '+b.skipped+' existing dates kept. Reopen Progress to refresh the chart.';}catch(error){if(v===version&&section.isConnected)status.textContent=error.message;}finally{button.disabled=false;}};}catch(error){rows=null;status.textContent=error.message;}};
}
